python3 - <<'PY'
import json, math
p=json.load(open('/root/diagpanel_policy_report.json'))
# check assumptions keys
ass=p['analysis']['assumptions']
print('assumptions keys',sorted(ass.keys()))
# check sorted panel_code
codes=[x['panel_code'] for x in p['analysis']['panels']]
print('sorted', codes==sorted(codes))
# check rounding: numeric fields should be cents-integer if float
bad=[]
for pan in p['analysis']['panels']:
    for k,v in pan.items():
        if isinstance(v,(int,)):
            continue
        if isinstance(v,(float,)):
            if abs(v*100-round(v*100))>1e-9:
                bad.append((pan['panel_code'],k,v))
        elif isinstance(v,str):
            pass

for k,v in p['analysis']['totals'].items():
    if isinstance(v,float) and abs(v*100-round(v*100))>1e-9:
        bad.append(('TOTALS',k,v))
print('rounding bad count',len(bad))
if bad[:10]:
    print('examples',bad[:10])
